// The MolKey package's InchiInfo and the parts of MolKey that need no
// structure checker; values from Python's modules in RDKit 2025.09.6,
// generated by running them on the same input.

use rdkit_cxx::Result;
use rdkit_cxx::chem::mol_key::inchi_info::{InchiInfo, Sp3Stereo};
use rdkit_cxx::chem::mol_key::mol_key::*;

fn sp3_tuple(sp3: &Sp3Stereo) -> (u32, u32, bool, &str) {
    (
        sp3.num_stereo,
        sp3.num_undef_stereo,
        sp3.is_meso,
        &sp3.stereo,
    )
}

#[test]
fn inchi_info() -> Result<()> {
    let info =
        InchiInfo::new("InChI=1S/C8H6BrCl2F/c9-7(10)5-3-1-2-4-6(5)8(11)12/h1-4,7-8H/t7?,8?")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C8H6BrCl2F/c9-7(10)5-3-1-2-4-6(5)8(11)12/h1-4,7-8H/t7?,8?"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(
        sp3_tuple(&sp3["main"]["non-isotopic"]),
        (2, 2, false, "7?,8?")
    );
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1/C4H4BrClN2/c5-4(6)3-1-2-7-8-3/h1-2,4H,(H,7,8)/t4?/f/h8H")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C4H4BrClN2/c5-4(6)3-1-2-7-8-3/h1-2,4H,(H,7,8)/t4?"
    );
    assert_eq!(info.parsed_inchi()["id"]["fixed_h"]["non-isotopic"], "/h8H");
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (1, 1, false, "4?"));
    assert_eq!(
        sp3_tuple(&sp3["fixed_h"]["non-isotopic"]),
        (0, 0, false, "")
    );
    assert_eq!(sp3.len(), 2);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (1, "(H,7,8)".to_owned()));
    assert_eq!(mh["fixed_h"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C4H10O2/c1-3(5)4(2)6/h3-6H,1-2H3/t3-,4+")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C4H10O2/c1-3(5)4(2)6/h3-6H,1-2H3/t3-,4+"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(
        sp3_tuple(&sp3["main"]["non-isotopic"]),
        (2, 0, true, "3-,4+")
    );
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C4H10O2/c1-3(5)4(2)6/h3-6H,1-2H3/t3-,4+/m1/s1")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C4H10O2/c1-3(5)4(2)6/h3-6H,1-2H3/t3-,4+/m1/s1"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(
        sp3_tuple(&sp3["main"]["non-isotopic"]),
        (2, 0, false, "3-,4+")
    );
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C6H12O2/c1-5-3-4-6(2)8-7-5/h5-6H,3-4H2,1-2H3/t5?,6?")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C6H12O2/c1-5-3-4-6(2)8-7-5/h5-6H,3-4H2,1-2H3/t5?,6?"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(
        sp3_tuple(&sp3["main"]["non-isotopic"]),
        (2, 2, false, "5?,6?")
    );
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C2H6O/c1-2-3/h3H,2H2,1H3/i1D")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C2H6O/c1-2-3/h3H,2H2,1H3"
    );
    assert_eq!(info.parsed_inchi()["id"]["main"]["isotopic"], "1D");
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3_tuple(&sp3["main"]["isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    assert_eq!(mh["main"]["isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1/C2H4O2/c1-2(3)4/h1H3,(H,3,4)/i1+1/f/h3H")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C2H4O2/c1-2(3)4/h1H3,(H,3,4)"
    );
    assert_eq!(info.parsed_inchi()["id"]["main"]["isotopic"], "1+1");
    assert_eq!(info.parsed_inchi()["id"]["fixed_h"]["non-isotopic"], "/h3H");
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3_tuple(&sp3["main"]["isotopic"]), (0, 0, false, ""));
    assert_eq!(
        sp3_tuple(&sp3["fixed_h"]["non-isotopic"]),
        (0, 0, false, "")
    );
    assert_eq!(sp3.len(), 2);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (1, "(H,3,4)".to_owned()));
    assert_eq!(mh["main"]["isotopic"], (0, "".to_owned()));
    assert_eq!(mh["fixed_h"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C10H14/c1-8(2)10-6-4-9(3)5-7-10/h4-8H,1-3H3")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C10H14/c1-8(2)10-6-4-9(3)5-7-10/h4-8H,1-3H3"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1/2CH4/h2*1H4/r2CH4")?;
    assert_eq!(
        info.parsed_inchi()["id_disconnected"]["main"]["non-isotopic"],
        "2CH4/h2*1H4"
    );
    assert_eq!(
        info.parsed_inchi()["id_reconnected"]["main"]["non-isotopic"],
        "2CH4"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(mh["main"]["non-isotopic"], (0, "".to_owned()));
    let info = InchiInfo::new("InChI=1S/C5H5N5/c6-4-3-5(9-1-7-3)10-2-8-4/h1-2H,(H3,6,7,8,9,10)")?;
    assert_eq!(
        info.parsed_inchi()["id"]["main"]["non-isotopic"],
        "C5H5N5/c6-4-3-5(9-1-7-3)10-2-8-4/h1-2H,(H3,6,7,8,9,10)"
    );
    let sp3 = info.get_sp3_stereo()?;
    assert_eq!(sp3_tuple(&sp3["main"]["non-isotopic"]), (0, 0, false, ""));
    assert_eq!(sp3.len(), 1);
    let mh = info.get_mobile_h();
    assert_eq!(
        mh["main"]["non-isotopic"],
        (1, "(H3,6,7,8,9,10)".to_owned())
    );
    assert!(InchiInfo::new("no layers").is_err());
    Ok(())
}

#[test]
fn codes() {
    assert_eq!(bad_set(), 986019);
    assert_eq!(error_bits_to_text(0), Vec::<&str>::new());
    assert_eq!(error_bits_to_text(1), ["BAD_MOLECULE"]);
    assert_eq!(
        error_bits_to_text(6),
        ["ALIAS_CONVERSION_FAILED", "TRANSFORMED"]
    );
    assert_eq!(
        error_bits_to_text(65539),
        [
            "BAD_MOLECULE",
            "ALIAS_CONVERSION_FAILED",
            "INCHI_COMPUTATION_ERROR"
        ]
    );
    assert_eq!(
        error_bits_to_text(986019),
        [
            "BAD_MOLECULE",
            "ALIAS_CONVERSION_FAILED",
            "STEREO_ERROR",
            "ATOM_CLASH",
            "ATOM_CHECK_FAILED",
            "SIZE_CHECK_FAILED",
            "STEREO_FORCED_BAD",
            "INCHI_COMPUTATION_ERROR",
            "RDKIT_CONVERSION_ERROR",
            "INCHI_READWRITE_ERROR",
            "NULL_MOL"
        ]
    );
    assert_eq!(
        error_bits_to_text(532480),
        ["TEMPLATE_TRANSFORMED", "NULL_MOL"]
    );
    assert_eq!(error_dict().len(), 18);
    assert_eq!(stereo_code_dict().len(), 17);
    assert_eq!(t_null_mol(), (524288, ""));
    assert_eq!((mol_key_version(), chiral_pos()), ("1", 12));
    assert_eq!(get_stereo_re(), r"^InChI=1S(.*?)/(t.*?)/m\d/s1(.*$)");
    assert_eq!(null_smiles_re(), r"^\s*$|^\s*NO_STRUCTURE\s*$");
    assert_eq!(pattern_null_mol(), r"^([\s0]+[1-9]+[\s]+V[\w]*)");
    assert_eq!(
        (
            inchi_computation_error(),
            rdkit_conversion_error(),
            inchi_readwrite_error(),
            null_mol()
        ),
        (65536, 131072, 262144, 524288)
    );
}
